<?php

namespace App\Support;

use Illuminate\Support\Facades\Context;
use Illuminate\Support\Str;

/**
 * The per-request correlation id. It is generated by the CMS (never taken from
 * the client), written to CMS audit events and sent to the gateway as
 * X-Request-Id so that both audit streams can be merged.
 */
final class RequestId
{
    public const CONTEXT_KEY = 'request_id';

    public static function current(): string
    {
        $id = Context::getHidden(self::CONTEXT_KEY);

        if (! is_string($id) || $id === '') {
            $id = self::regenerate();
        }

        return $id;
    }

    public static function regenerate(): string
    {
        $id = (string) Str::uuid();
        Context::addHidden(self::CONTEXT_KEY, $id);
        Context::add(self::CONTEXT_KEY, $id); // also appears in log context

        return $id;
    }
}
